"""Reward-only audit for slow movement credit in a multi-rate controller.

Historical actor checkpoints did not persist the learned standard critic, so
the exact old movement advantages cannot be reconstructed after training.  This
module therefore compares two transparent, zero-baseline GAE proxies on the
same deterministic trajectories:

* frame GAE: lambda decay is applied every simulator frame;
* macro GAE: the five rewards generated by one held movement are first
  aggregated with micro discounting, then lambda decay is applied once per
  movement decision and bootstrapping uses gamma**H.

The proxy is diagnostic rather than a claim about a learned critic.  It answers
whether the reward timing alone supports introducing a dedicated macro critic.
"""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple

import numpy as np


def _rankdata(values: np.ndarray) -> np.ndarray:
    values = np.asarray(values, dtype=np.float64)
    order = np.argsort(values, kind="mergesort")
    ranks = np.empty(values.size, dtype=np.float64)
    sorted_values = values[order]
    start = 0
    while start < values.size:
        end = start + 1
        while end < values.size and sorted_values[end] == sorted_values[start]:
            end += 1
        ranks[order[start:end]] = 0.5 * (start + end - 1) + 1.0
        start = end
    return ranks


def _spearman(x: np.ndarray, y: np.ndarray) -> float:
    if x.size < 3 or y.size != x.size:
        return float("nan")
    x_rank = _rankdata(x)
    y_rank = _rankdata(y)
    x_centered = x_rank - np.mean(x_rank)
    y_centered = y_rank - np.mean(y_rank)
    denominator = np.sqrt(
        np.sum(x_centered ** 2) * np.sum(y_centered ** 2))
    if denominator <= 1.0e-12:
        return float("nan")
    return float(np.sum(x_centered * y_centered) / denominator)


def compute_frame_and_macro_gae(
    movement_rewards: np.ndarray,
    gamma: float,
    gae_lambda: float,
    interval: int,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    """Return frame GAE and macro GAE evaluated at movement boundaries."""
    rewards = np.asarray(movement_rewards, dtype=np.float64)
    if rewards.ndim != 2:
        raise ValueError("movement rewards must have shape (frames, agents)")
    interval = max(1, int(interval))
    frame_count, agent_count = rewards.shape

    frame_gae = np.zeros_like(rewards)
    running = np.zeros(agent_count, dtype=np.float64)
    for frame in reversed(range(frame_count)):
        running = rewards[frame] + gamma * gae_lambda * running
        frame_gae[frame] = running

    boundaries = np.arange(0, frame_count, interval, dtype=np.int64)
    macro_rewards = np.zeros(
        (boundaries.size, agent_count), dtype=np.float64)
    for macro_index, start in enumerate(boundaries):
        stop = min(start + interval, frame_count)
        discounts = gamma ** np.arange(stop - start, dtype=np.float64)
        macro_rewards[macro_index] = np.sum(
            rewards[start:stop] * discounts[:, None], axis=0)

    macro_gae = np.zeros_like(macro_rewards)
    running.fill(0.0)
    macro_discount = gamma ** interval
    for macro_index in reversed(range(boundaries.size)):
        running = (
            macro_rewards[macro_index]
            + macro_discount * gae_lambda * running
        )
        macro_gae[macro_index] = running
    return boundaries, frame_gae[boundaries], macro_gae


def _finite_interval(values: Sequence[float]) -> Tuple[float, float]:
    finite = np.asarray(values, dtype=np.float64)
    finite = finite[np.isfinite(finite)]
    if finite.size == 0:
        return float("nan"), float("nan")
    return (
        float(np.quantile(finite, 0.025)),
        float(np.quantile(finite, 0.975)),
    )


def _episode_rows(
    movement_rewards: np.ndarray,
    pd_history: np.ndarray,
    gamma: float,
    gae_lambda: float,
    interval: int,
) -> List[Dict[str, float]]:
    pd = np.asarray(pd_history, dtype=np.float64)
    boundaries, frame_gae, macro_gae = compute_frame_and_macro_gae(
        movement_rewards, gamma, gae_lambda, interval)
    rows: List[Dict[str, float]] = []
    for index, frame in enumerate(boundaries):
        stop = int(frame) + int(interval)
        # The initial reset has no realized previous P_D baseline and the final
        # partial hold is not a valid H-frame decision outcome.
        if frame == 0 or stop > len(pd):
            continue
        future_per_target = np.mean(pd[frame:stop], axis=0)
        future_ordered = np.sort(future_per_target)
        previous_ordered = np.sort(pd[frame - 1])
        rows.append({
            "frame_advantage": float(np.mean(frame_gae[index])),
            "macro_advantage": float(np.mean(macro_gae[index])),
            "future_worst_delta": float(
                future_ordered[0] - previous_ordered[0]),
            "future_weak3_delta": float(
                np.mean(future_ordered[:min(3, future_ordered.size)])
                - np.mean(previous_ordered[
                    :min(3, previous_ordered.size)])),
        })
    return rows


def _statistics(rows: Sequence[Dict[str, float]]) -> Dict[str, float]:
    if not rows:
        return {
            "frame_worst_corr": float("nan"),
            "macro_worst_corr": float("nan"),
            "worst_corr_gain": float("nan"),
            "frame_weak3_corr": float("nan"),
            "macro_weak3_corr": float("nan"),
            "weak3_corr_gain": float("nan"),
        }
    frame = np.asarray([row["frame_advantage"] for row in rows])
    macro = np.asarray([row["macro_advantage"] for row in rows])
    worst = np.asarray([row["future_worst_delta"] for row in rows])
    weak3 = np.asarray([row["future_weak3_delta"] for row in rows])
    frame_worst = _spearman(frame, worst)
    macro_worst = _spearman(macro, worst)
    frame_weak3 = _spearman(frame, weak3)
    macro_weak3 = _spearman(macro, weak3)
    return {
        "frame_worst_corr": frame_worst,
        "macro_worst_corr": macro_worst,
        "worst_corr_gain": macro_worst - frame_worst,
        "frame_weak3_corr": frame_weak3,
        "macro_weak3_corr": macro_weak3,
        "weak3_corr_gain": macro_weak3 - frame_weak3,
    }


def summarize_temporal_credit_proxy(
    movement_reward_histories: Sequence[np.ndarray],
    pd_histories: Sequence[np.ndarray],
    gamma: float,
    gae_lambda: float,
    interval: int,
    bootstrap_samples: int = 2000,
    bootstrap_seed: int = 20260723,
) -> Dict[str, object]:
    """Compare frame and macro GAE proxies with episode-cluster intervals."""
    if len(movement_reward_histories) != len(pd_histories):
        raise ValueError("reward and P_D histories must align")
    episodes = [
        _episode_rows(rewards, pd, gamma, gae_lambda, interval)
        for rewards, pd in zip(movement_reward_histories, pd_histories)
    ]
    flat = [row for episode in episodes for row in episode]
    stats = _statistics(flat)
    summary: Dict[str, object] = {
        "eval_temporal_proxy_episode_count": int(len(episodes)),
        "eval_temporal_proxy_boundary_count": int(len(flat)),
        "eval_temporal_proxy_note": (
            "reward-only zero-baseline GAE proxy; historical actor-only "
            "checkpoint does not contain the learned movement critic"),
    }
    summary.update({
        f"eval_temporal_proxy_{key}": float(value)
        for key, value in stats.items()
    })

    rng = np.random.default_rng(int(bootstrap_seed))
    boot = {key: [] for key in stats}
    episode_count = len(episodes)
    if episode_count > 0:
        for _ in range(max(1, int(bootstrap_samples))):
            indices = rng.integers(0, episode_count, size=episode_count)
            sampled = [
                row for index in indices for row in episodes[int(index)]]
            sampled_stats = _statistics(sampled)
            for key, value in sampled_stats.items():
                boot[key].append(value)
    for key, values in boot.items():
        low, high = _finite_interval(values)
        summary[f"eval_temporal_proxy_{key}_ci95"] = [low, high]

    worst_gain_ci = summary[
        "eval_temporal_proxy_worst_corr_gain_ci95"]
    summary["eval_temporal_proxy_gate_pass"] = bool(
        sum(bool(rows) for rows in episodes) >= 10
        and float(stats["worst_corr_gain"]) > 0.10
        and np.isfinite(worst_gain_ci[0])
        and worst_gain_ci[0] > 0.0
    )
    summary["eval_temporal_proxy_gate_rule"] = (
        "at least 10 independent episodes and macro-minus-frame Spearman "
        "gain for future 5-frame worst > 0.10 with 95% lower bound > 0"
    )
    return summary
